    for (final java.lang.String assetPath : assetPaths) {
        final org.apache.sling.api.resource.Resource assetResource = config.getResourceResolver().getResource(assetPath);
        if ((assetResource != null) && com.day.cq.dam.commons.util.DamUtil.isAsset(assetResource)) {
            final com.adobe.aem.commons.assetshare.content.AssetModel asset = modelFactory.getModelFromWrappedRequest(config.getRequest(), assetResource, com.adobe.aem.commons.assetshare.content.AssetModel.class);
            // Unescape else gets double-escaped and the link breaks
            java.lang.String url = assetDetailsResolver.getFullUrl(config, asset);
            if (org.apache.commons.lang3.StringUtils.isBlank(url)) {
                com.adobe.aem.commons.assetshare.components.actions.share.impl.EmailShareServiceImpl.log.warn("Could not determine an Asset Details page path for asset at [ {} ]", assetPath);
                continue;
            }
            // Unescape the URL since externalizer also escapes, resulting in a breaking, double-escaped URLs
            // This is required since assetDetailsResolver.getFullUrl(config, asset) performs its own escaping.
            url = com.day.text.Text.unescape(url);
            if (com.adobe.aem.commons.assetshare.util.RequireAem.ServiceType.AUTHOR.equals(requireAem.getServiceType())) {
                url = externalizer.authorLink(config.getResourceResolver(), url);
            } else {
                url = externalizer.externalLink(config.getResourceResolver(), cfg.externalizerDomain(), url);
            }
            sb.append("<li><a href=\"");
            sb.append(url);
            sb.append("\">");
            sb.append(asset.getTitle());
            sb.append("</a></li>");
        }
    }
    sb.append("</ul>");
    return sb.toString();
}

