    final java.util.List<java.lang.String> tagLabels = new java.util.ArrayList<>();
    final org.apache.sling.api.resource.Resource metadataResource = asset.adaptTo(org.apache.sling.api.resource.Resource.class).getChild("jcr:content/metadata");
    final com.day.cq.tagging.TagManager tagManager = metadataResource.getResourceResolver().adaptTo(com.day.cq.tagging.TagManager.class);
    if ((metadataResource == null) || (tagManager == null)) {
        return tagLabels;
    }
    final com.day.cq.tagging.Tag[] tags = tagManager.getTags(metadataResource);
    if (tags != null) {
        final com.day.cq.wcm.api.components.ComponentContext componentContext = getComponentContext(request);
        final com.day.cq.wcm.api.Page currentPage = (componentContext != null) ? componentContext.getPage() : null;
        final java.util.Locale locale = (currentPage == null) ? request.getLocale() : currentPage.getLanguage(false);
        for (final com.day.cq.tagging.Tag tag : tags) {
            tagLabels.add(tag.getTitle(locale));
        }
    }
    java.util.Collections.sort(tagLabels);
    return tagLabels;
}

